import { say } from "./texts.js";

const email = /^[^\s@]+@[^\s@]+$/;

function length(value) {
  return Array.from(value).length;
}

/** Whether a value matches a pattern; one the browser cannot read matches nothing. */
function matches(pattern, value) {
  try {
    return new RegExp(pattern, "u").test(value);
  } catch {
    return false;
  }
}

/** What is wrong with a field's value by its keywords; undefined when nothing is. */
export function fieldProblem(field, value, texts) {
  if (value === "") {
    return field.required ? say(texts, "screens.required") : undefined;
  }
  if (field.minLength !== undefined && length(value) < field.minLength) {
    return say(texts, { text: "screens.minLength", count: field.minLength });
  }
  if (field.maxLength !== undefined && length(value) > field.maxLength) {
    return say(texts, { text: "screens.maxLength", count: field.maxLength });
  }
  if (field.pattern !== undefined && !matches(field.pattern, value)) {
    return say(texts, "screens.pattern");
  }
  if (field.type === "email" && !email.test(value)) {
    return say(texts, "screens.email");
  }
  if (field.type === "number") {
    const number = Number(value);
    if (!Number.isFinite(number)) {
      return say(texts, "screens.number");
    }
    if (field.step !== undefined && !Number.isInteger(number / field.step)) {
      return say(texts, { text: "screens.step", count: field.step });
    }
    if (field.min !== undefined && number < field.min) {
      return say(texts, { text: "screens.minimum", count: field.min });
    }
    if (field.max !== undefined && number > field.max) {
      return say(texts, { text: "screens.maximum", count: field.max });
    }
  }
  if (field.type === "date" && !isDate(value)) {
    return say(texts, "screens.date");
  }
  return undefined;
}

/** Whether a value is a day of the calendar, written yyyy-mm-dd. */
function isDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }
  const day = new Date(value + "T00:00:00Z");
  return !Number.isNaN(day.getTime()) && day.toISOString().slice(0, 10) === value;
}

/** The value of a rule over the values of a page or a row: ["field", name], ["value", constant], or an operator and its operands. */
export function evaluate(rule, values) {
  switch (rule[0]) {
    case "field":
      return values[rule[1]] ?? null;
    case "value":
      return rule[1];
    case "!":
      return !evaluate(rule[1], values);
    case "size": {
      const value = evaluate(rule[1], values);
      return typeof value === "string" ? length(value) : 0;
    }
    case "&&":
      return evaluate(rule[1], values) === true && evaluate(rule[2], values) === true;
    case "||":
      return evaluate(rule[1], values) === true || evaluate(rule[2], values) === true;
    default:
      break;
  }
  const left = evaluate(rule[1], values);
  const right = evaluate(rule[2], values);
  switch (rule[0]) {
    case "==":
      return left === right;
    case "!=":
      return left !== right;
    default:
      break;
  }
  if (typeof left !== typeof right || (typeof left !== "string" && typeof left !== "number")) {
    return false;
  }
  switch (rule[0]) {
    case "<":
      return left < right;
    case "<=":
      return left <= right;
    case ">":
      return left > right;
    case ">=":
      return left >= right;
    default:
      return false;
  }
}

/**
 * What stops a task page being sent: each field's problem by field, then
 * each rule across fields that does not hold, under its field or, with
 * none, under "".
 */
export function problemsOf(schema, values, texts) {
  const problems = {};
  for (const field of schema.fields) {
    const problem = fieldProblem(field, values[field.name] ?? "", texts);
    if (problem !== undefined) {
      problems[field.name] = problem;
    }
  }
  for (const check of schema.checks) {
    const at = check.field ?? "";
    if (problems[at] === undefined && evaluate(check.rule, values) !== true) {
      problems[at] = say(texts, check.message);
    }
  }
  return problems;
}

/** The key under which a field's second entry is held. */
export function againOf(field) {
  return field.name + "#again";
}

/** A field's value as the service has it: a number, a boolean, text, or null when it is empty. */
export function typed(field, value) {
  if (field.type === "checkbox") {
    return value === "true";
  }
  if (value === "") {
    return null;
  }
  return field.type === "number" ? Number(value) : value;
}

/** The values a form's rules read: the loaded record's fields, then the form's own, typed. */
export function recordOf(fields, values, loaded) {
  const record = { ...loaded };
  for (const field of fields) {
    record[field.name] = typed(field, values[field.name] ?? "");
  }
  return record;
}

/**
 * The sections as the person sees them: a field is read-only unless they
 * hold its readOnlyUnless, and hidden unless they hold its hiddenUnless,
 * folded into readOnly and hiddenWhen so the rest of the page reads one
 * rule.
 */
export function forCaller(sections, held) {
  const always = ["value", true];
  return sections.map((section) => ({
    ...section,
    fields: section.fields.map((field) => ({
      ...field,
      ...(field.readOnlyUnless !== undefined && !held.includes(field.readOnlyUnless) ? { readOnly: true } : {}),
      ...(field.hiddenUnless !== undefined && !held.includes(field.hiddenUnless) ? { hiddenWhen: always } : {}),
    })),
  }));
}

/** Whether a field is left out of the page while its rule holds. */
export function hidden(field, record) {
  return field.hiddenWhen !== undefined && evaluate(field.hiddenWhen, record) === true;
}

/** Whether a field is shown and not changed. */
export function locked(field, record) {
  return field.readOnly === true || (field.readOnlyWhen !== undefined && evaluate(field.readOnlyWhen, record) === true);
}

/**
 * What stops a form being sent: each field shown that the person may
 * change, by its keywords and its second entry, then each check across the
 * fields that does not hold, under its field or, with none, under "".
 */
export function formProblems(fields, checks, values, record, texts) {
  const problems = {};
  for (const field of fields) {
    if (hidden(field, record) || locked(field, record)) {
      continue;
    }
    const problem = fieldProblem(field, values[field.name] ?? "", texts);
    if (problem !== undefined) {
      problems[field.name] = problem;
    } else if (field.twice !== undefined && (values[againOf(field)] ?? "") !== (values[field.name] ?? "")) {
      problems[againOf(field)] = say(texts, "screens.again");
    }
  }
  for (const check of checks) {
    const at = check.field ?? "";
    if (problems[at] === undefined && evaluate(check.rule, record) !== true) {
      problems[at] = say(texts, check.message);
    }
  }
  return problems;
}

/** The refusal of a status among a page's failed states: the one of that status, or the one with none. */
export function refusalOf(failed, status) {
  return failed.find((f) => f.status === status) ?? failed.find((f) => f.status === undefined);
}

/** A value as a view or a table shows it: none, yes or no, or its text. */
export function shown(value, texts) {
  if (value === null || value === undefined || value === "") {
    return say(texts, "screens.none");
  }
  if (typeof value === "boolean") {
    return say(texts, value ? "screens.yes" : "screens.no");
  }
  return String(value);
}

/** Whether a value is an object with fields, not an array. */
export function isRecord(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
